<script setup lang="ts">
import {defineAsyncComponent,onMounted,ref} from 'vue';
import {useRoute} from 'vue-router';
import type {Statistics,SingleStatistics,VersionContext,QuestionSummary} from '@survey/shared';
import {api} from '../api';
import {useVersions} from '../reporting-client';
import VersionPicker from '../components/VersionPicker.vue';
import NumberSummary from '../components/NumberSummary.vue';
import UiIcon from '../components/UiIcon.vue';
import {optionPercentage} from '../statistics-display';
const ChoiceChart=defineAsyncComponent(()=>import('../components/ChoiceChart.vue'));
const route=useRoute(),id=String(route.params.surveyId),qid=route.params.questionId?String(route.params.questionId):null,versions=useVersions(id),selected=ref<number|null>(null),context=ref<VersionContext|null>(null),rows=ref<QuestionSummary[]>([]),busy=ref(true),error=ref('');
async function select(version:number){selected.value=version;busy.value=true;error.value='';try{const data=await api<Statistics|SingleStatistics>(`/surveys/${id}/${qid?`questions/${qid}/statistics`:'statistics'}?version=${version}`);context.value=data;rows.value='questionSummaries'in data?data.questionSummaries:[data.questionSummary];}catch(e){error.value=(e as Error).message;context.value=null;rows.value=[];}finally{busy.value=false;}}
async function init(){busy.value=true;error.value='';try{await versions.load();const v=route.query.version?Number(route.query.version):versions.latest.value;if(v)await select(v);}catch(e){error.value=(e as Error).message;}finally{busy.value=false;}}
onMounted(init);
</script>
<template><section class="report-page"><RouterLink class="back" :to="`/surveys/${id}`">← 返回问卷</RouterLink><div class="report-heading"><span class="report-heading-icon"><UiIcon name="chart" :size="28"/></span><div><h1 tabindex="-1">{{qid?'单题统计':'分版本统计'}}</h1><p class="muted">按所选发布版本统计有效答卷和选择次数，不跨版本合并。</p></div></div><p v-if="error" class="error" role="alert">{{error}} <button class="quiet" @click="init">重试</button></p><div class="report-version-bar"><div><UiIcon name="layers" :size="20"/><strong>报告版本</strong><span class="muted">选择要查看的发布快照</span></div><VersionPicker v-if="versions.items.value.length" :items="versions.items.value" :selected="selected" :more="!!versions.cursor.value" :disabled="busy" @select="select" @more="versions.load(true)" /></div><p v-if="busy" role="status">正在统计…</p><p v-else-if="!versions.items.value.length&&!error" class="panel">问卷尚未发布，没有统计数据。</p>
<template v-if="context"><div class="count-strip panel"><div>累计答卷<strong data-testid="cumulative">{{context.cumulativeResponseCount}} 份</strong></div><div>当前发布版本<strong data-testid="current-count">{{context.currentVersionResponseCount}} 份</strong></div><div>所选 v{{context.selectedVersion}}<strong data-testid="selected-count">{{context.selectedVersionResponseCount}} 份</strong></div></div><div class="editor-actions report-links"><RouterLink :to="`/surveys/${id}/responses?version=${context.selectedVersion}`">查看该版答卷</RouterLink><RouterLink :to="`/surveys/${id}/versions?version=${context.selectedVersion}`">查看该版定义</RouterLink><RouterLink v-if="qid" :to="`/surveys/${id}/statistics?version=${context.selectedVersion}`">整卷统计</RouterLink></div>
<article v-for="row in rows" :key="`${context.selectedVersion}:${row.questionId}`" class="panel statistic-card" :data-question-id="row.questionId"><div class="statistic-heading"><span class="statistic-type"><UiIcon :name="row.type" :size="20"/></span><div><span class="question-type-label">{{ ({single:'单选题',multiple:'多选题',text:'文本题',number:'数字题'})[row.type] }}</span><h2>{{row.title}}</h2></div><span class="answer-count">有效回答 <strong>{{row.answeredCount}}</strong> 份</span></div><template v-if="row.optionCounts"><p class="muted chart-caption">占比 = 该选项选择次数 ÷ 本题有效回答份数；不计跳过或留空的答卷。</p><div class="distribution-layout"><div class="distribution-chart"><ChoiceChart v-if="row.answeredCount>0" :row="row" /><p v-else class="chart-empty">暂无有效回答，收到答卷后显示图表。</p></div><div class="distribution-detail"><h3>选项明细</h3><div class="table-scroll"><table><caption class="visually-hidden">{{row.title}}的选项次数和回答占比</caption><thead><tr><th scope="col">选项</th><th scope="col">选择次数</th><th scope="col">占比</th></tr></thead><tbody><tr v-for="option in row.optionCounts" :key="option.optionId"><td>{{option.label}}</td><td>{{option.count}}</td><td>{{optionPercentage(option.count,row.answeredCount)}}%</td></tr></tbody></table></div></div></div></template><NumberSummary v-if="row.type==='number'" :title="row.title" :average="row.average" /><RouterLink v-if="['text','number'].includes(row.type)" :to="`/surveys/${id}/questions/${row.questionId}/answers?version=${context.selectedVersion}`">查看回答内容</RouterLink><RouterLink v-if="!qid" class="single-stat-link" :to="`/surveys/${id}/questions/${row.questionId}/statistics?version=${context.selectedVersion}`">单题统计</RouterLink></article></template></section></template>
